package lt.viko.eif.imazolevska.jaxws.runner;

import lt.viko.eif.imazolevska.jaxws.client.Director;
import lt.viko.eif.imazolevska.jaxws.client.DirectorService;
import lt.viko.eif.imazolevska.jaxws.client.DirectorServiceImplService;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * Tests the SOAP web service on application startup using the client
 * generated by the wsimport tool. Prints all directors and the director with id 1.
 */

@Component
public class DirectorClientRunner implements CommandLineRunner {

    /**
     * Calls both web service operations through the generated client and prints the results.
     *
     * @param args command line arguments, not used
     */

    @Override
    public void run(String... args) {
        DirectorService port = new DirectorServiceImplService().getDirectorServiceImplPort();
        List<Director> directors = port.getAllDirectors();
        System.out.println();
        System.out.println("Directors:");
        for (Director director : directors) {
            System.out.println(
                    "ID: " + director.getId() +
                            " first name: " + director.getFirstName() +
                            " last name: " + director.getLastName() +
                            " birth year: " + director.getBirthYear() +
                            " average rating: " + director.getAverageRating() +
                            " active: " + director.isActive() +
                            " main genre: " + director.getMainGenre() +
                            " movies: " + director.getMovies().getMovie().size());
        }
        System.out.println();
        System.out.println("Director with ID=1:");
        Director director = port.getDirectorById(1);

        System.out.println(
                "ID: " + director.getId() +
                        " first name: " + director.getFirstName() +
                        " last name: " + director.getLastName() +
                        " birth year: " + director.getBirthYear() +
                        " average rating: " + director.getAverageRating() +
                        " active: " + director.isActive() +
                        " main genre: " + director.getMainGenre() +
                        " movies: " + director.getMovies().getMovie().size());

    }

}